import 'package:material_ui/material_ui.dart';
import 'package:flutter_svg/flutter_svg.dart';
import '../kora_ui.dart';

/// Expressions of Kapi, the Kora capybara. Each one is a vector asset in
/// `assets/images/mascot/kapi_{name}.svg` generated by tool/mascot; replacing
/// those files with final artwork needs no code change.
enum MascotMood {
  /// Bienvenida: saluda.
  welcome,
  /// Explicación: señala lo que se está explicando.
  explain,
  /// Motivación: brazos arriba.
  motivate,
  /// Espera o generación en curso (nunca con porcentajes).
  waiting,
  /// Éxito.
  success,
  /// Error o dificultad.
  error;

  String get asset => 'assets/images/mascot/kapi_$name.svg';

  String get semanticLabel => switch (this) {
    welcome => 'Kapi, la capibara de Kora, saluda',
    explain => 'Kapi señala lo que explica',
    motivate => 'Kapi te anima',
    waiting => 'Kapi espera tranquila',
    success => 'Kapi celebra',
    error => 'Kapi está preocupada',
  };
}

/// Kapi with light, optional motion: a slow float, a gentle "breath" while
/// waiting and a cross-fade between expressions. With reduced motion
/// (MediaQuery.disableAnimations) it is fully static.
class KoraMascot extends StatefulWidget {
  const KoraMascot({super.key, required this.mood, this.size = 120, this.animate = true});
  final MascotMood mood;
  final double size;
  final bool animate;

  @override
  State<KoraMascot> createState() => _KoraMascotState();
}

class _KoraMascotState extends State<KoraMascot> with SingleTickerProviderStateMixin {
  late final AnimationController _motion = AnimationController(vsync: this, duration: const Duration(milliseconds: 2600));

  bool _reduceMotion(BuildContext context) => !widget.animate || MediaQuery.disableAnimationsOf(context);

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    _syncMotion();
  }

  @override
  void didUpdateWidget(covariant KoraMascot oldWidget) {
    super.didUpdateWidget(oldWidget);
    _syncMotion();
  }

  void _syncMotion() {
    if (_reduceMotion(context)) {
      _motion.stop();
      _motion.value = 0;
    } else if (!_motion.isAnimating) {
      _motion.repeat(reverse: true);
    }
  }

  @override
  void dispose() {
    _motion.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final reduce = _reduceMotion(context);
    final picture = SvgPicture.asset(
      widget.mood.asset,
      key: ValueKey(widget.mood),
      width: widget.size,
      height: widget.size,
      excludeFromSemantics: true,
    );
    final switcher = AnimatedSwitcher(
      duration: reduce ? Duration.zero : const Duration(milliseconds: 280),
      switchInCurve: Curves.easeOutBack,
      transitionBuilder: (child, animation) => FadeTransition(
        opacity: animation,
        child: ScaleTransition(scale: Tween(begin: .92, end: 1.0).animate(animation), child: child),
      ),
      child: picture,
    );
    return Semantics(
      image: true,
      label: widget.mood.semanticLabel,
      child: SizedBox.square(
        dimension: widget.size,
        child: reduce
            ? switcher
            : AnimatedBuilder(
                animation: _motion,
                child: switcher,
                builder: (context, child) {
                  final t = Curves.easeInOutSine.transform(_motion.value);
                  final float = (t - .5) * widget.size * .04;
                  final breath = widget.mood == MascotMood.waiting ? 1 + t * .025 : 1.0;
                  return Transform.translate(
                    offset: Offset(0, float),
                    child: Transform.scale(scale: breath, alignment: Alignment.bottomCenter, child: child),
                  );
                },
              ),
      ),
    );
  }
}

/// Kapi with a speech bubble: the building block of the welcome tour and of
/// the waiting/success/error screens around the first plan.
class MascotMessage extends StatelessWidget {
  const MascotMessage({
    super.key,
    required this.mood,
    required this.message,
    this.title,
    this.mascotSize = 96,
    this.dark = false,
  });

  final MascotMood mood;
  final String? title;
  final String message;
  final double mascotSize;

  /// On forest backgrounds the bubble keeps ivory for contrast.
  final bool dark;

  @override
  Widget build(BuildContext context) {
    final bubble = Container(
      padding: const EdgeInsets.fromLTRB(16, 14, 16, 14),
      decoration: BoxDecoration(
        color: dark ? Kora.ivory : Colors.white,
        borderRadius: const BorderRadius.only(
          topLeft: Radius.circular(20), topRight: Radius.circular(20),
          bottomRight: Radius.circular(20), bottomLeft: Radius.circular(6),
        ),
        border: Border.all(color: const Color(0x140F2E25)),
        boxShadow: const [BoxShadow(color: Color(0x140F2E25), blurRadius: 14, offset: Offset(0, 4))],
      ),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
        if (title != null)
          Padding(
            padding: const EdgeInsets.only(bottom: 4),
            child: Text(title!, style: const TextStyle(color: Kora.forest, fontWeight: FontWeight.w800, fontSize: 16)),
          ),
        Text(message, style: const TextStyle(color: Kora.forest, fontSize: 14, height: 1.45)),
      ]),
    );
    return Semantics(
      container: true,
      liveRegion: true,
      child: Row(crossAxisAlignment: CrossAxisAlignment.end, children: [
        KoraMascot(mood: mood, size: mascotSize),
        const SizedBox(width: 8),
        Expanded(child: Padding(padding: EdgeInsets.only(bottom: mascotSize * .35), child: bubble)),
      ]),
    );
  }
}
